//! 🧪️ Full pin and role intents preserve their exact inverse and close every denied or cancelled native prefix.
use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{receive,source,grant,observe,drain,central_fragment,project_record};
#[derive(semio_framework_value::RetireOwned)]struct Payload{link:Option<ArtifactLink>}
struct Weather;struct Referenced;
impl RootLinkPath<Payload> for Weather{const SLOT:RootLinkSlot=RootLinkSlot::Weather;fn desired(p:RetainedCloneRef<'_,Payload>)->Option<RetainedCloneRef<'_,ArtifactLink>>{p.get().link.as_ref()?;Some(p.project(0,|p|p.link.as_ref().unwrap()))}}
impl RootLinkPath<Payload> for Referenced{const SLOT:RootLinkSlot=RootLinkSlot::ReferencedModel;fn desired(p:RetainedCloneRef<'_,Payload>)->Option<RetainedCloneRef<'_,ArtifactLink>>{p.get().link.as_ref()?;Some(p.project(0,|p|p.link.as_ref().unwrap()))}}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut values=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{values.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{values.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{values.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}if d.depth>0{values.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g})}values}
fn run<S:RootLinkPath<Payload>>(case:&serde_json::Value,law:&serde_json::Value){let body=law["bodyBytes"].as_u64().unwrap()as usize;let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut document=document["document"].take();document["model"]=helpers::corpus()["model"].clone();let field=match S::SLOT{RootLinkSlot::Weather=>"weatherLink",RootLinkSlot::ReferencedModel=>"referencedModel"};document[field]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let foreign_original=source(receive::<EnergyModelSnapshot>(&document));let foreign_payload=source(Payload{link:None});let payload=source(Payload{link:if case["value"].is_null(){None}else{Some(receive::<ArtifactLink>(&case["value"]))}});
 for cutoff in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=RootLinkPreparation::<S,Payload>::new();let mut turns=0;while !owner.ready()&&cutoff.is_none_or(|cut|turns<cut){if turns>0{let(r,h)=observe(||owner.demand(foreign_payload.borrow(),None,original.borrow(),body));assert!(r.is_err());assert_eq!(h,(0,0));}if turns>1{let(r,h)=observe(||owner.demand(payload.borrow(),None,foreign_original.borrow(),body));assert!(r.is_err());assert_eq!(h,(0,0));}let d=owner.demand(payload.borrow(),None,original.borrow(),body).unwrap();assert!(d.copy_bytes<=body&&d.capacity_bytes<=law["capacityBytes"].as_u64().unwrap()as usize,"{} native root birth exceeds original copy/capacity policy: {d:?}",case["id"]);let g=grant(d);for g in denied(g,d){let(s,h)=observe(||owner.advance(payload.borrow(),None,original.borrow(),body,g).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(payload.borrow(),None,original.borrow(),body).unwrap(),d);}let(s,h)=observe(||owner.advance(payload.borrow(),None,original.borrow(),body,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(s.progress().fits(g));turns+=1;assert!(turns<100000,"{} native root did not decide",case["id"]);}
 if cutoff.is_none(){let outcome=owner.outcome().unwrap();assert_eq!(outcome.as_str(),case["outcome"].as_str().unwrap());if outcome==RowOutcome::Changed{let(diff,_)=owner.take(grant(owner.take_demand().unwrap())).unwrap().unwrap();let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let after=match S::SLOT{RootLinkSlot::Weather=>post.weather_link.get(),RootLinkSlot::ReferencedModel=>post.referenced_model.get()};let expected=if case["after"].is_null(){None}else{Some(receive::<ArtifactLink>(&case["after"]))};assert_eq!(after,&expected);drain(expected);assert_eq!(post.model.geometry.identity(),original.borrow().get().model.geometry.identity());let(value,_)=owner.take_inverse(grant(owner.take_inverse_demand().unwrap())).unwrap().unwrap();assert_eq!(value.as_ref(),S::SLOT.source(original.borrow()).get().as_ref());drain(value);drain(post);drain(diff);}}
 owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demand(body).unwrap();assert!(d.copy_bytes<=body&&d.capacity_bytes<=law["capacityBytes"].as_u64().unwrap()as usize,"native original close quote {d:?}");let g=grant(d);for g in denied(g,d){let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(body).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(index<99999,"native root close did not finish at {d:?}");}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));
 }drain(payload);drain(foreign_payload);drain(foreign_original);drain(original);
}
#[test]fn original_root_links_preserve_complete_pin_role_and_sparse_inverse_across_all_denied_and_cancelled_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){if case["slot"]=="weather_link"{run::<Weather>(case,&law)}else{run::<Referenced>(case,&law)}}}
